  private var affectedStores: [AppStore] {
    var seen: Set<ObjectIdentifier> = [ObjectIdentifier(self)]
    return [self]
      + WindowRegistry.shared.allStores.filter { seen.insert(ObjectIdentifier($0)).inserted }
  }

